package com.nexusdrive.common.util;
import java.nio.ByteBuffer; import java.security.*; import javax.crypto.*; import javax.crypto.spec.*;
public final class AesEncryptionUtil { private static final int IV=12,TAG=128; private AesEncryptionUtil(){} public static SecretKey generateKey(){try{KeyGenerator g=KeyGenerator.getInstance("AES");g.init(256);return g.generateKey();}catch(GeneralSecurityException e){throw new IllegalStateException(e);}} public static byte[] encrypt(byte[] data,SecretKey key){try{byte[] iv=new byte[IV];SecureRandom.getInstanceStrong().nextBytes(iv);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,key,new GCMParameterSpec(TAG,iv));byte[] out=c.doFinal(data);return ByteBuffer.allocate(IV+out.length).put(iv).put(out).array();}catch(GeneralSecurityException e){throw new IllegalStateException("Encryption failed",e);}} public static byte[] decrypt(byte[] encrypted,SecretKey key){if(encrypted.length<IV+16)throw new IllegalArgumentException("Invalid ciphertext");try{ByteBuffer b=ByteBuffer.wrap(encrypted);byte[] iv=new byte[IV];b.get(iv);byte[] data=new byte[b.remaining()];b.get(data);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,key,new GCMParameterSpec(TAG,iv));return c.doFinal(data);}catch(GeneralSecurityException e){throw new IllegalArgumentException("Decryption/authentication failed",e);}} }
